Run this in a tab on the origin whose /api goes to the rebuilt BFF, so the session cookie is sent. Set PREFIX to the prefix used in the seed SQL. It returns a JSON summary that contains no cookie or token.

```js
(async () => {
  const PREFIX = 'ws09s8-REPLACE_ME'; // same value as the psql variable prefix
  const TURNS = 400, PAGE = 100;
  const thread = PREFIX + '-thread', foreignTurn = PREFIX + '-foreign';
  const base = '/api/v1/chat/threads/' + encodeURIComponent(thread) + '/messages';
  const failures = [];
  const fail = (m) => failures.push(m);
  const get = async (query) => {
    const r = await fetch(base + (query ? '?' + query : ''), {credentials: 'same-origin', cache: 'no-store', headers: {accept: 'application/json'}});
    let body = null; try { body = await r.json(); } catch (_) {}
    return {status: r.status, body};
  };
  const ident = await fetch('/api/v1/session/current', {credentials: 'same-origin', cache: 'no-store'}).then(r => r.json()).catch(() => null);
  // 1. tail pages, newest back to oldest
  const bodies = []; let before = '';
  for (;;) {
    const r = await get('limit=' + PAGE + (before ? '&before=' + encodeURIComponent(before) : ''));
    if (r.status !== 200) { fail('page ' + (bodies.length + 1) + ' answered ' + r.status + ' ' + JSON.stringify(r.body && r.body.error)); break; }
    bodies.push(r.body);
    if (!('has_more' in r.body)) fail('page ' + bodies.length + ' has no has_more key');
    if (r.body.has_more !== true) break;
    before = r.body.messages[0].message_id;
    if (bodies.length > TURNS / PAGE + 2) { fail('the tail pages did not end after ' + bodies.length + ' pages'); break; }
  }
  if (bodies.length !== TURNS / PAGE) fail('expected ' + TURNS / PAGE + ' pages, read ' + bodies.length);
  const turns = [];
  [...bodies].reverse().forEach((b, i) => { if ((b.messages || []).length !== PAGE) fail('page ' + (bodies.length - i) + ' carried ' + (b.messages || []).length); turns.push(...(b.messages || [])); });
  const ids = turns.map(t => t.message_id);
  const expected = Array.from({length: TURNS}, (_, n) => PREFIX + '-m' + String(n).padStart(4, '0'));
  if (ids.length !== TURNS) fail('expected ' + TURNS + ' turns, saw ' + ids.length);
  if (new Set(ids).size !== ids.length) fail('a turn repeated across pages');
  if (JSON.stringify(ids) !== JSON.stringify(expected)) fail('the turns are not in conversation order');
  const flags = bodies.map(b => b.has_more);
  const wantFlags = bodies.map((_, i) => i < bodies.length - 1);
  if (JSON.stringify(flags) !== JSON.stringify(wantFlags)) fail('has_more was ' + JSON.stringify(flags));
  // 2. unpaged read unchanged
  const u = await get('');
  const unpaged = {status: u.status, hasMoreKey: !!(u.body && 'has_more' in u.body), count: u.body && u.body.messages ? u.body.messages.length : null, first: u.body && u.body.messages && u.body.messages[0] ? u.body.messages[0].content : null};
  if (u.status !== 200) fail('unpaged read answered ' + u.status);
  if (unpaged.hasMoreKey) fail('an unpaged read must not carry has_more');
  if (unpaged.count !== TURNS) fail('unpaged read returned ' + unpaged.count);
  if (unpaged.first !== 'turn 0') fail('unpaged first turn was ' + JSON.stringify(unpaged.first));
  // 3. refused parameters
  const refused = [];
  for (const q of ['limit=0', 'limit=201', 'limit=fifty', 'before=' + PREFIX + '-m0100', 'limit=10&before=a%26limit%3D1', 'limit=10&before=' + foreignTurn]) {
    const r = await get(q);
    refused.push({query: q, status: r.status, code: r.body && r.body.error && r.body.error.code});
    if (r.status !== 400) fail(q + ' answered ' + r.status + ', expected 400');
  }
  return {ok: failures.length === 0, failures, identity: {userId: ident && ident.data && ident.data.user && ident.data.user.id, orgId: ident && ident.data && ident.data.org && ident.data.org.id}, pages: bodies.length, pageSizes: bodies.map(b => (b.messages || []).length), hasMore: flags, turns: ids.length, unique: new Set(ids).size, inOrder: JSON.stringify(ids) === JSON.stringify(expected), unpaged, refused};
})()
```

The five refusals except the foreign cursor should report code `invalid_request`, because the BFF refuses them. The foreign cursor should report `invalid_thread_request`, because session-core refuses it.
